from pathlib import Path
from tempfile import mkdtemp
from hashlib import sha256
import base64,json,os,shutil,sqlite3,subprocess
home=Path('/home/purge');daily=home/'.dsh-improved';installed=home/'tools/dsh-purge-personal-1.1.77-personal.1';runtime=home/'tools/harness-improved-runtime/node_modules'
def digest(path):return sha256(path.read_bytes()).hexdigest()

def identity():
    databases={}
    for p in (daily/'redteam/engagements').glob('*/assets.db'):
        value=sha256()
        with sqlite3.connect(p.as_uri()+'?mode=ro',uri=True,timeout=3) as db:
            for row in db.iterdump():value.update((row+'\n').encode())
        databases[str(p)]=value.hexdigest()
    return {'program':{str(p.relative_to(installed)):digest(p) for p in installed.rglob('*')
                       if p.is_file() and '__pycache__' not in p.parts},
            'config':{str(p):digest(p) for p in [daily/'.credentials.yaml',daily/'cordis.patch.yml',
                 daily/'profiles/web/package.json',daily/'profiles/web/cordis.patch.yml']},
            'pins':{name:digest(home/'tools/security-workbench'/name) for name in ['images.json','rules.json']},
            'runtime':digest(runtime/'@deepseek-ai/dsh-tools/lib/index.js'),'databases':databases,
            'outsideMountNamespace':os.readlink('/proc/self/ns/mnt'),'homeInode':daily.stat().st_ino}
assert os.geteuid()==1000
before=identity()
root=Path(mkdtemp(prefix='r3-receipt-coverage-',dir=home/'.cache'))
try:
 for name,text in PAYLOAD.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(text));assert digest(p)==CHECKS[name]
 result=subprocess.run([str(home/'.local/node/bin/node'),'--test',str(root/'work/harness-purge-improved/tests/review-quality-gate.test.mjs')],cwd=root,env={**os.environ,'NODE_OPTIONS':''},capture_output=True,text=True,timeout=45)
 python_test=subprocess.run(['/usr/bin/python3','-I','-B',str(root/'scripts/reviewer_snapshot.test.py')],cwd=root,capture_output=True,text=True,timeout=30)
 assert python_test.returncode==0,python_test.stderr
 live=subprocess.run(['/usr/bin/python3','-I','-B',str(root/'live.py')],cwd=root,capture_output=True,text=True,timeout=55)
 assert live.returncode==0,live.stderr
 actual=json.loads(live.stdout)
 assert all(digest(root/name)==value for name,value in CHECKS.items())
 assert identity()==before
 output={'exitCode':result.returncode,'stdout':result.stdout,'stderr':result.stderr,'candidateSourceSha256':CHECKS,'dailyProgramFilesMatched':len(before['program']),'dailyDatabasesLogicallyMatched':len(before['databases']),'dailyConfigPinsRuntimeMatched':True,'pythonSnapshotTests':{'exitCode':python_test.returncode,'stderr':python_test.stderr},'live':actual}
finally:
 shutil.rmtree(root)
output['temporaryRemoved']=not root.exists()
print(json.dumps(output))
